import { useEffect, useState } from 'react'
import { Eye, Hand, Ear, Flame, Flower2, Coffee, Leaf, Pause, Play, RotateCcw, Wind, ArrowRight, Sparkles } from 'lucide-react'
import { cn } from '../../../../lib/utils'

const MAX_CYCLES = 4

const BREATH_PHASES = [
  { label: 'Breathe in', seconds: 4, ring: 'inhale' },
  { label: 'Hold', seconds: 4, ring: 'hold-full' },
  { label: 'Breathe out', seconds: 4, ring: 'exhale' },
  { label: 'Hold', seconds: 4, ring: 'hold-empty' },
] as const

const GROUNDING_STEPS = [
  { icon: Eye, count: 5, prompt: 'things you can see' },
  { icon: Hand, count: 4, prompt: 'things you can touch' },
  { icon: Ear, count: 3, prompt: 'things you can hear' },
  { icon: Flower2, count: 2, prompt: 'things you can smell' },
  { icon: Coffee, count: 1, prompt: 'thing you can taste' },
] as const

type BreatheCardProps = {
  onCycleComplete: (cycles: number) => void
}

function BreatheCard({ onCycleComplete }: BreatheCardProps) {
  const [running, setRunning] = useState(false)
  const [phaseIndex, setPhaseIndex] = useState(0)
  const [secondsLeft, setSecondsLeft] = useState<number>(BREATH_PHASES[0].seconds)
  const [cycles, setCycles] = useState(0)
  const [sessionDone, setSessionDone] = useState(false)
  const [sessions, setSessions] = useState(() =>
    parseInt(localStorage.getItem('mind_breathe_sessions') || '0', 10))

  useEffect(() => {
    if (cycles > 0) {
      onCycleComplete(cycles)
    }
  }, [cycles, onCycleComplete])

  // Stop and mark session complete when MAX_CYCLES is reached
  useEffect(() => {
    if (cycles >= MAX_CYCLES && !sessionDone) {
      setRunning(false)
      setSessionDone(true)
      setSessions((s) => {
        const next = s + 1
        localStorage.setItem('mind_breathe_sessions', String(next))
        return next
      })
    }
  }, [cycles, sessionDone])

  useEffect(() => {
    if (!running) return
    const timer = window.setInterval(() => {
      setSecondsLeft((s) => {
        if (s > 1) return s - 1
        setPhaseIndex((p) => {
          const next = (p + 1) % BREATH_PHASES.length
          if (next === 0) setCycles((c) => c + 1)
          return next
        })
        return BREATH_PHASES[(phaseIndex + 1) % BREATH_PHASES.length].seconds
      })
    }, 1000)
    return () => window.clearInterval(timer)
  }, [running, phaseIndex])

  const reset = () => {
    setRunning(false)
    setPhaseIndex(0)
    setSecondsLeft(BREATH_PHASES[0].seconds)
    setCycles(0)
    setSessionDone(false)
  }

  const phase = BREATH_PHASES[phaseIndex]

  if (sessionDone) {
    return (
      <section className="mind-card mind-card--breathe mind-tint-lavender" aria-label="Breathing exercise">
        <Wind className="mind-card-watermark" size={104} strokeWidth={1.3} aria-hidden="true" />
        <div className="mind-card-head">
          <span className="mind-card-icon">
            <Wind size={16} />
          </span>
          <div>
            <h2 className="mind-card-title">Breathe</h2>
            <p className="mind-card-sub">4 in · 4 hold · 4 out · 4 hold</p>
          </div>
        </div>
        <div className="mind-breathe-complete">
          <span className="mind-breathe-complete-badge">
            <Sparkles size={22} />
          </span>
          <p className="mind-breathe-complete-text">4 cycles complete</p>
          <p className="mind-breathe-complete-sub">You stayed with your breath. That's a real rep.</p>
        </div>
        <div className="mind-breathe-controls">
          <button type="button" className="mind-ghost-btn" onClick={reset}>
            <RotateCcw size={12} />
            Again
          </button>
          <span className="mind-sessions-badge">
            <Flame size={10} />
            {sessions} {sessions === 1 ? 'session' : 'sessions'}
          </span>
        </div>
      </section>
    )
  }

  return (
    <section className="mind-card mind-card--breathe mind-tint-lavender" aria-label="Breathing exercise">
      <Wind className="mind-card-watermark" size={104} strokeWidth={1.3} aria-hidden="true" />
      <div className="mind-card-head">
        <span className="mind-card-icon">
          <Wind size={16} />
        </span>
        <div>
          <h2 className="mind-card-title">Breathe</h2>
          <p className="mind-card-sub">4 in · 4 hold · 4 out · 4 hold</p>
        </div>
      </div>

      <div className="mind-breathe-stage">
        <div className={cn('mind-breathe-ring', `mind-breathe-ring--${running ? phase.ring : 'rest'}`)}>
          <div className="mind-breathe-core">
            {running ? (
              <>
                <span className="mind-breathe-phase">{phase.label}</span>
                <span className="mind-breathe-count">{secondsLeft}</span>
              </>
            ) : (
              <span className="mind-breathe-phase">Ready?</span>
            )}
          </div>
        </div>
      </div>

      <div className="mind-breathe-controls">
        <button type="button" className="mind-solid-btn" onClick={() => setRunning((r) => !r)}>
          {running ? <Pause size={12} /> : <Play size={12} />}
          {running ? 'Pause' : 'Begin'}
        </button>
        <button type="button" className="mind-ghost-btn" onClick={reset}>
          <RotateCcw size={12} />
        </button>
        {cycles > 0 && (
          <span className="mind-breathe-cycles">
            {cycles}/{MAX_CYCLES}
          </span>
        )}
        {sessions > 0 && (
          <span className="mind-sessions-badge">
            <Flame size={10} />
            {sessions}
          </span>
        )}
      </div>
    </section>
  )
}

function GroundingCard() {
  const [step, setStep] = useState(0)
  const [sessions, setSessions] = useState(() =>
    parseInt(localStorage.getItem('mind_grounding_sessions') || '0', 10))
  const done = step >= GROUNDING_STEPS.length

  const advanceStep = () => {
    const next = step + 1
    if (next >= GROUNDING_STEPS.length) {
      setSessions((s) => {
        const newCount = s + 1
        localStorage.setItem('mind_grounding_sessions', String(newCount))
        return newCount
      })
    }
    setStep(next)
  }

  return (
    <section className="mind-card mind-card--grounding mind-tint-sage" aria-label="5-4-3-2-1 grounding">
      <Leaf className="mind-card-watermark" size={104} strokeWidth={1.3} aria-hidden="true" />
      <div className="mind-card-head">
        <span className="mind-card-icon">
          <Leaf size={16} />
        </span>
        <div>
          <h2 className="mind-card-title">Come to your senses</h2>
          <p className="mind-card-sub">5 · 4 · 3 · 2 · 1 grounding</p>
        </div>
      </div>

      <div className="mind-grounding-dots" aria-hidden="true">
        {GROUNDING_STEPS.map((s, i) => (
          <span key={s.prompt} className={cn('mind-grounding-dot', i < step && 'is-done', i === step && 'is-active')} />
        ))}
      </div>

      {done ? (
        <div className="mind-grounding-body">
          <span className="mind-grounding-badge">
            <Sparkles size={18} />
          </span>
          <p className="mind-grounding-prompt">Back in the room. You were here the whole time.</p>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <button type="button" className="mind-ghost-btn" onClick={() => setStep(0)}>
              <RotateCcw size={12} />
              Again
            </button>
            {sessions > 0 && (
              <span className="mind-sessions-badge">
                <Flame size={10} />
                {sessions} {sessions === 1 ? 'grounding' : 'groundings'}
              </span>
            )}
          </div>
        </div>
      ) : (
        <div className="mind-grounding-body">
          {(() => {
            const { icon: Icon, count, prompt } = GROUNDING_STEPS[step]
            return (
              <>
                <span className="mind-grounding-badge">
                  <Icon size={18} />
                </span>
                <p className="mind-grounding-prompt">
                  Name <strong>{count}</strong> {prompt}
                </p>
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                  <button type="button" className="mind-solid-btn" onClick={advanceStep}>
                    Named them
                    <ArrowRight size={12} />
                  </button>
                  {sessions > 0 && (
                    <span className="mind-sessions-badge">
                      <Flame size={10} />
                      {sessions}
                    </span>
                  )}
                </div>
              </>
            )
          })()}
        </div>
      )}
    </section>
  )
}

export { BreatheCard, GroundingCard }

import { useState } from 'react'
import { Anchor, RefreshCw, Pencil, Check } from 'lucide-react'
import { cn } from '../../../../lib/utils'
import { MIND_VALUE_TAGS } from '../mind-types'

type TodaysAnchorCardProps = {
  intention: string
  onIntentionChange: (value: string) => void
  valueTag: string | null
  onValueTagChange: (tag: string | null) => void
  availableTags: string[]
  onAddTag: (tag: string) => void
  onRemoveTag: (tag: string) => void
  saving?: boolean
  affirmation: string
  onNextAffirmation: () => void
}

function TodaysAnchorCard({
  intention,
  onIntentionChange,
  valueTag,
  onValueTagChange,
  availableTags,
  onAddTag,
  onRemoveTag,
  saving = false,
  affirmation,
  onNextAffirmation,
}: TodaysAnchorCardProps) {
  const [isEditing, setIsEditing] = useState(false)
  const [draft, setDraft] = useState('')
  const [isPickingTag, setIsPickingTag] = useState(false)
  const [isAddingTag, setIsAddingTag] = useState(false)
  const [newTagText, setNewTagText] = useState('')

  const startEditing = () => {
    setDraft(intention)
    setIsEditing(true)
    setIsPickingTag(false)
  }

  const finishEditing = () => {
    onIntentionChange(draft.trim())
    setIsEditing(false)
  }

  const submitTag = () => {
    const val = newTagText.trim()
    if (val) {
      onAddTag(val)
      onValueTagChange(val)
      setNewTagText('')
    }
    setIsAddingTag(false)
    setIsPickingTag(false)
  }

  return (
    <section className="mind-card mind-card--anchor mind-tint-butter" aria-label="Today's anchor">
      <Anchor className="mind-card-watermark" size={104} strokeWidth={1.3} aria-hidden="true" />

      <div className="mind-card-head">
        <span className="mind-card-icon">
          <Anchor size={16} />
        </span>
        <div style={{ flex: 1 }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', width: '100%' }}>
            <h2 className="mind-card-title">Today's anchor</h2>
            {saving && (
              <span className="mind-saving-badge">
                <span className="mind-saving-dot animate-pulse" />
                saving
              </span>
            )}
          </div>
          <p className="mind-card-sub">One intention, held lightly</p>
        </div>
      </div>

      {/* Intention: quote display (click to edit) or inline edit mode */}
      {isEditing ? (
        <div className="mind-anchor-edit-row">
          <input
            type="text"
            className="mind-anchor-input"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="What matters today?"
            autoFocus
            onKeyDown={(e) => {
              if (e.key === 'Enter') finishEditing()
              if (e.key === 'Escape') setIsEditing(false)
            }}
          />
          <button type="button" className="mind-solid-btn" onClick={finishEditing}>
            <Check size={12} />
            Done
          </button>
        </div>
      ) : (
        <div
          className="mind-anchor-display"
          role="button"
          tabIndex={0}
          onClick={startEditing}
          onKeyDown={(e) => e.key === 'Enter' && startEditing()}
          aria-label={intention ? `Intention: ${intention}. Click to edit.` : 'Set your intention for today'}
        >
          {intention ? (
            <p className="mind-anchor-quote">"{intention}"</p>
          ) : (
            <p className={cn('mind-anchor-quote', 'mind-anchor-quote--empty')}>What matters today?</p>
          )}
          <button
            type="button"
            className="mind-anchor-edit-btn"
            onClick={(e) => { e.stopPropagation(); startEditing() }}
            aria-label="Edit intention"
            tabIndex={-1}
          >
            <Pencil size={11} />
          </button>
        </div>
      )}

      {/* Focus tag: show only the active one (or a "Set focus" prompt) */}
      <div className="mind-anchor-tag-area">
        {valueTag ? (
          <>
            <span className="mind-anchor-active-tag">
              <span aria-hidden="true">●</span>
              {valueTag}
              <button
                type="button"
                className="mind-anchor-tag-clear"
                onClick={() => { onValueTagChange(null); setIsPickingTag(false) }}
                aria-label={`Clear focus: ${valueTag}`}
              >
                ×
              </button>
            </span>
            <button
              type="button"
              className="mind-anchor-tag-change-btn"
              onClick={() => setIsPickingTag((p) => !p)}
              aria-expanded={isPickingTag}
            >
              {isPickingTag ? 'close' : 'change ▾'}
            </button>
          </>
        ) : (
          <button
            type="button"
            className="mind-anchor-set-focus-btn"
            onClick={() => setIsPickingTag((p) => !p)}
            aria-expanded={isPickingTag}
          >
            {isPickingTag ? '▲ close' : '+ Set focus'}
          </button>
        )}
      </div>

      {/* Tag picker — inline, only when isPickingTag */}
      {isPickingTag && (
        <div className="mind-anchor-tag-picker" role="group" aria-label="Choose focus tag">
          {availableTags.map((tag) => {
            const isDefault = MIND_VALUE_TAGS.includes(tag as any)
            return (
              <button
                key={tag}
                type="button"
                className={cn('mind-tag mind-tag--value', valueTag === tag && 'is-active')}
                aria-pressed={valueTag === tag}
                onClick={() => {
                  onValueTagChange(valueTag === tag ? null : tag)
                  setIsPickingTag(false)
                }}
              >
                {tag}
                {!isDefault && (
                  <span
                    className="mind-tag-delete"
                    role="button"
                    aria-label={`Delete custom tag ${tag}`}
                    onClick={(e) => {
                      e.stopPropagation()
                      onRemoveTag(tag)
                    }}
                  >
                    &times;
                  </span>
                )}
              </button>
            )
          })}
          {isAddingTag ? (
            <form
              onSubmit={(e) => { e.preventDefault(); submitTag() }}
              className="mind-tag-form"
            >
              <input
                type="text"
                className="mind-tag-input-field"
                value={newTagText}
                onChange={(e) => setNewTagText(e.target.value)}
                placeholder="Tag name..."
                maxLength={15}
                autoFocus
                onBlur={() => setTimeout(submitTag, 150)}
              />
            </form>
          ) : (
            <button
              type="button"
              className="mind-tag mind-tag--add"
              onClick={() => setIsAddingTag(true)}
              aria-label="Add custom tag"
            >
              + Tag
            </button>
          )}
        </div>
      )}

      {/* Affirmation */}
      <div className="mind-affirmation">
        <p className="mind-affirmation-text">"{affirmation}"</p>
        <button type="button" className="mind-ghost-btn" onClick={onNextAffirmation} aria-label="Another affirmation">
          <RefreshCw size={12} />
        </button>
      </div>
    </section>
  )
}

export { TodaysAnchorCard }

import { useCallback, useEffect, useMemo, useState, useRef } from 'react'
import toast from 'react-hot-toast'
import type { MindDistortionTag, MindEntry, MindSummary } from './mind-types'
import { AFFIRMATIONS, buildSeedEntries, mindAddDays, mindIsoDate, MIND_VALUE_TAGS } from './mind-types'
import {
  convertMindEntry,
  createMindEntry,
  updateMindEntry,
  fetchMindEntries,
  fetchMindSummary,
  saveMindMood,
  updateMindStatus,
} from '../../../lib/api'
import { MindHeader } from './components/mind-header'
import { MindInboxCard } from './components/mind-inbox-card'
import { TodaysAnchorCard } from './components/todays-anchor-card'
import { EvidenceLockerCard } from './components/evidence-locker-card'
import { WorryParkingCard } from './components/worry-parking-card'
import { GratitudeCard } from './components/gratitude-card'
import { BreatheCard, GroundingCard } from './components/calm-tools-card'
import { SosOverlay } from './components/sos-overlay'
import './mind-overview.css'

const RELEASE_ANIMATION_MS = 620

let localIdCounter = 0
function tempId(): string {
  localIdCounter += 1
  return `mind-temp-${Date.now()}-${localIdCounter}`
}

function MindOverviewDashboard() {
  const [selectedDate] = useState(() => mindIsoDate())
  const [entries, setEntries] = useState<MindEntry[]>([])
  const [summary, setSummary] = useState<MindSummary | null>(null)
  const [releasingIds, setReleasingIds] = useState<ReadonlySet<string>>(new Set())
  const [mood, setMood] = useState<number | null>(null)
  const [sosOpen, setSosOpen] = useState(false)
  const [affirmationIndex, setAffirmationIndex] = useState(0)

  // Anchor persistence state
  const [intention, setIntention] = useState('')
  const [valueTag, setValueTag] = useState<string | null>(null)
  const [saving, setSaving] = useState(false)
  const saveTimeoutRef = useRef<number | null>(null)

  // Custom tags list (with localStorage fallback)
  const [availableTags, setAvailableTags] = useState<string[]>(() => {
    const saved = localStorage.getItem('custom_mind_tags')
    if (saved) {
      try {
        const parsed = JSON.parse(saved)
        if (Array.isArray(parsed)) {
          return Array.from(new Set([...MIND_VALUE_TAGS, ...parsed]))
        }
      } catch (e) {
        console.error('Failed to parse custom tags', e)
      }
    }
    return [...MIND_VALUE_TAGS]
  })

  const load = useCallback(async () => {
    try {
      const [entriesRes, summaryRes] = await Promise.all([
        fetchMindEntries(),
        fetchMindSummary(selectedDate),
      ])
      const fetched = entriesRes.data ?? []
      setEntries(fetched)
      setSummary(summaryRes.data ?? null)
      setMood(summaryRes.data?.moodScore ?? null)

      // Sync intention from backend
      const anchor = fetched.find((e) => e.type === 'INTENTION' && e.date === selectedDate)
      if (anchor) {
        setIntention(anchor.text)
        setValueTag(anchor.valueTag || null)
      } else {
        setIntention('')
        setValueTag(null)
      }
    } catch {
      // Never leave the tab blank in dev / offline — fall back to local seeds.
      const seeds = buildSeedEntries(selectedDate)
      setEntries(seeds)
      setSummary(null)

      // Sync intention from seeds
      const anchor = seeds.find((e) => e.type === 'INTENTION' && e.date === selectedDate)
      if (anchor) {
        setIntention(anchor.text)
        setValueTag(anchor.valueTag || null)
      } else {
        setIntention('')
        setValueTag(null)
      }
    }
  }, [selectedDate])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    void load()
  }, [load])

  // Clear timeout on unmount
  useEffect(() => {
    return () => {
      if (saveTimeoutRef.current) {
        window.clearTimeout(saveTimeoutRef.current)
      }
    }
  }, [])

  const refreshSummary = useCallback(async () => {
    try {
      const res = await fetchMindSummary(selectedDate)
      setSummary(res.data ?? null)
    } catch {
      /* keep the last-known summary */
    }
  }, [selectedDate])

  const saveIntention = useCallback(async (text: string, tag: string | null) => {
    setSaving(true)
    try {
      const existing = entries.find((e) => e.type === 'INTENTION' && e.date === selectedDate)
      if (existing) {
        const res = await updateMindEntry(existing.id, {
          text: text.trim(),
          type: 'INTENTION',
          valueTag: tag as any,
          date: selectedDate
        })
        setEntries((prev) => prev.map((e) => (e.id === existing.id ? res.data : e)))
      } else {
        const res = await createMindEntry({
          text: text.trim(),
          type: 'INTENTION',
          valueTag: tag as any,
          date: selectedDate
        })
        setEntries((prev) => [...prev, res.data])
      }
    } catch (err) {
      console.error('Failed to save today\'s anchor', err)
      toast.error('Failed to save intention.')
    } finally {
      setSaving(false)
    }
  }, [entries, selectedDate])

  const handleValueTagChange = useCallback((newTag: string | null) => {
    setValueTag(newTag)
    void saveIntention(intention, newTag)
  }, [intention, saveIntention])

  const handleIntentionChange = useCallback((newText: string) => {
    setIntention(newText)
    if (saveTimeoutRef.current) {
      window.clearTimeout(saveTimeoutRef.current)
    }
    saveTimeoutRef.current = window.setTimeout(() => {
      void saveIntention(newText, valueTag)
    }, 800)
  }, [valueTag, saveIntention])

  const handleAddTag = useCallback((newTag: string) => {
    const trimmed = newTag.trim()
    if (!trimmed) return
    setAvailableTags((prev) => {
      if (prev.includes(trimmed)) return prev
      const next = [...prev, trimmed]
      const customTagsOnly = next.filter((t) => !MIND_VALUE_TAGS.includes(t as any))
      localStorage.setItem('custom_mind_tags', JSON.stringify(customTagsOnly))
      return next
    })
  }, [])

  const handleRemoveTag = useCallback((tagToRemove: string) => {
    if (MIND_VALUE_TAGS.includes(tagToRemove as any)) return
    setAvailableTags((prev) => {
      const next = prev.filter((t) => t !== tagToRemove)
      const customTagsOnly = next.filter((t) => !MIND_VALUE_TAGS.includes(t as any))
      localStorage.setItem('custom_mind_tags', JSON.stringify(customTagsOnly))
      return next
    })
    if (valueTag === tagToRemove) {
      setValueTag(null)
      void saveIntention(intention, null)
    }
  }, [valueTag, intention, saveIntention])

  // Log breathing cycles to database and update streak in real-time
  const handleBreatheLogged = useCallback(async (currentCycles: number) => {
    const todayBreathEntry = entries.find((e) => e.type === 'BREATH' && e.date === selectedDate)
    const text = `Breathed for ${currentCycles} ${currentCycles === 1 ? 'cycle' : 'cycles'}`
    try {
      if (todayBreathEntry) {
        const res = await updateMindEntry(todayBreathEntry.id, {
          text,
          type: 'BREATH',
          date: selectedDate
        })
        setEntries((prev) => prev.map((e) => (e.id === todayBreathEntry.id ? res.data : e)))
      } else {
        const res = await createMindEntry({
          text,
          type: 'BREATH',
          date: selectedDate
        })
        setEntries((prev) => [...prev, res.data])
        toast.success('Mindful breathing logged! Streak updated 🔥')
      }
      void refreshSummary()
    } catch (err) {
      console.error('Failed to log breathe cycle', err)
    }
  }, [entries, selectedDate, refreshSummary])

  const patchEntry = useCallback((id: string, patch: Partial<MindEntry>) => {
    setEntries((prev) => prev.map((entry) => (entry.id === id ? { ...entry, ...patch } : entry)))
  }, [])

  const handleCapture = useCallback(
    async (text: string) => {
      const optimistic: MindEntry = {
        id: tempId(),
        type: 'THOUGHT',
        text,
        status: 'OPEN',
        date: selectedDate,
        createdAt: new Date().toISOString(),
      }
      setEntries((prev) => [optimistic, ...prev])
      try {
        const res = await createMindEntry({ text, date: selectedDate })
        setEntries((prev) => prev.map((e) => (e.id === optimistic.id ? res.data : e)))
      } catch {
        setEntries((prev) => prev.filter((e) => e.id !== optimistic.id))
        toast.error('Could not save that — try again.')
      }
    },
    [selectedDate],
  )

  const handleDo = useCallback(
    async (id: string) => {
      patchEntry(id, { status: 'CONVERTED', resolvedAt: new Date().toISOString() })
      toast.success('Turned into a task. It has a home now — not your head.')
      try {
        const res = await convertMindEntry(id)
        patchEntry(id, res.data)
        void refreshSummary()
      } catch {
        toast.error('Could not create the task — bringing it back.')
        void load()
      }
    },
    [patchEntry, refreshSummary, load],
  )

  const handlePark = useCallback(
    async (id: string, days: number) => {
      const reviewDate = mindAddDays(selectedDate, days)
      patchEntry(id, { status: 'PARKED', reviewDate })
      toast.success('Parked. It will come back when you said — not before.')
      try {
        await updateMindStatus(id, { status: 'PARKED', reviewDate })
      } catch {
        toast.error('Could not park that — try again.')
        void load()
      }
    },
    [patchEntry, selectedDate, load],
  )

  const handleRelease = useCallback(
    (id: string) => {
      setReleasingIds((prev) => new Set(prev).add(id))
      window.setTimeout(async () => {
        patchEntry(id, { status: 'RELEASED', resolvedAt: new Date().toISOString() })
        setReleasingIds((prev) => {
          const next = new Set(prev)
          next.delete(id)
          return next
        })
        try {
          await updateMindStatus(id, { status: 'RELEASED' })
          void refreshSummary()
        } catch {
          /* the thought is already gone from view; a reload will reconcile */
        }
      }, RELEASE_ANIMATION_MS)
    },
    [patchEntry, refreshSummary],
  )

  const handleReframeSave = useCallback(
    async (id: string, reframedText: string, distortionTag: MindDistortionTag | null) => {
      patchEntry(id, {
        status: 'RESOLVED',
        reframedText,
        distortionTag,
        resolvedAt: new Date().toISOString(),
      })
      toast.success("Reframed. That's a rep for your mind.")
      try {
        await updateMindStatus(id, { status: 'RESOLVED', reframedText, distortionTag })
        void refreshSummary()
      } catch {
        toast.error('Could not save the reframe — try again.')
        void load()
      }
    },
    [patchEntry, refreshSummary, load],
  )

  const handleAddWin = useCallback(
    async (text: string) => {
      const optimistic: MindEntry = {
        id: tempId(),
        type: 'WIN',
        text,
        status: 'OPEN',
        date: selectedDate,
        createdAt: new Date().toISOString(),
      }
      setEntries((prev) => [...prev, optimistic])
      toast.success('Filed as evidence.')
      try {
        const res = await createMindEntry({ type: 'WIN', text, date: selectedDate })
        setEntries((prev) => prev.map((e) => (e.id === optimistic.id ? res.data : e)))
      } catch {
        setEntries((prev) => prev.filter((e) => e.id !== optimistic.id))
        toast.error('Could not save that win — try again.')
      }
    },
    [selectedDate],
  )

  const handleAddGratitude = useCallback(
    async (text: string) => {
      const optimistic: MindEntry = {
        id: tempId(),
        type: 'GRATITUDE',
        text,
        status: 'OPEN',
        date: selectedDate,
        createdAt: new Date().toISOString(),
      }
      setEntries((prev) => [...prev, optimistic])
      try {
        const res = await createMindEntry({ type: 'GRATITUDE', text, date: selectedDate })
        setEntries((prev) => prev.map((e) => (e.id === optimistic.id ? res.data : e)))
      } catch {
        setEntries((prev) => prev.filter((e) => e.id !== optimistic.id))
        toast.error('Could not save that — try again.')
      }
    },
    [selectedDate],
  )

  const handleBringBack = useCallback(
    async (id: string) => {
      patchEntry(id, { status: 'OPEN', reviewDate: null })
      try {
        await updateMindStatus(id, { status: 'OPEN' })
      } catch {
        void load()
      }
    },
    [patchEntry, load],
  )

  const handleMoodSelect = useCallback(
    async (value: number) => {
      const next = mood === value ? null : value
      setMood(next)
      if (next != null) {
        try {
          await saveMindMood(selectedDate, next)
        } catch {
          /* mood is a soft signal; don't nag on failure */
        }
      }
    },
    [mood, selectedDate],
  )

  const thoughts = useMemo(() => entries.filter((e) => e.type === 'THOUGHT'), [entries])
  const openThoughts = useMemo(() => thoughts.filter((e) => e.status === 'OPEN'), [thoughts])
  const parked = useMemo(() => thoughts.filter((e) => e.status === 'PARKED'), [thoughts])
  const wins = useMemo(() => entries.filter((e) => e.type === 'WIN'), [entries])
  const gratitude = useMemo(() => entries.filter((e) => e.type === 'GRATITUDE'), [entries])
  const closedLoops = useMemo(
    () => thoughts.filter((e) => e.status === 'CONVERTED' || e.status === 'RESOLVED').slice(-1),
    [thoughts],
  )
  const stats = useMemo(
    () => ({
      captured: thoughts.length,
      converted: thoughts.filter((e) => e.status === 'CONVERTED').length,
      reframed: thoughts.filter((e) => Boolean(e.reframedText)).length,
      released: thoughts.filter((e) => e.status === 'RELEASED').length,
    }),
    [thoughts],
  )

  return (
    <div className="mind-dashboard">
      <MindHeader
        dateIso={selectedDate}
        mood={mood}
        onMoodSelect={handleMoodSelect}
        streakDays={summary?.streakDays ?? 0}
        onOpenSos={() => setSosOpen(true)}
      />

      <div className="mind-grid">
        <BreatheCard onCycleComplete={handleBreatheLogged} />

        <GroundingCard />

        <TodaysAnchorCard
          intention={intention}
          onIntentionChange={handleIntentionChange}
          valueTag={valueTag}
          onValueTagChange={handleValueTagChange}
          availableTags={availableTags}
          onAddTag={handleAddTag}
          onRemoveTag={handleRemoveTag}
          saving={saving}
          affirmation={AFFIRMATIONS[affirmationIndex]}
          onNextAffirmation={() => setAffirmationIndex((i) => (i + 1) % AFFIRMATIONS.length)}
        />

        <MindInboxCard
          openThoughts={openThoughts}
          closedLoops={closedLoops}
          releasingIds={releasingIds}
          stats={stats}
          onCapture={handleCapture}
          onDo={handleDo}
          onPark={handlePark}
          onRelease={handleRelease}
          onReframeSave={handleReframeSave}
        />

        <EvidenceLockerCard wins={wins} autoEvidence={summary} onAddWin={handleAddWin} />

        <WorryParkingCard parked={parked} onBringBack={handleBringBack} onRelease={handleRelease} />

        <GratitudeCard gratitude={gratitude} onAddGratitude={handleAddGratitude} />
      </div>

      <SosOverlay open={sosOpen} onClose={() => setSosOpen(false)} />
    </div>
  )
}

export { MindOverviewDashboard }

import { useState, useEffect, useRef, useCallback } from 'react'
import { X, Loader2, ClipboardCheck, Camera, CheckCircle, AlertTriangle, RotateCcw, Upload, Wifi, Bell, Scan, Shield, TrendingUp, Sparkles } from 'lucide-react'
import { createPortal } from 'react-dom'
import toast from 'react-hot-toast'
import { addFoodEntry, updateFoodEntry, type MealAnalysisApiResponse, type ClinicalFlag, type IngredientBreakdown } from '../../../../lib/api'
import { useNotifications } from '../../../../contexts/NotificationContext'

// ─── Types ────────────────────────────────────────────────────────────────

type Phase = 'input' | 'processing' | 'results'

const MEAL_TYPES = ['Breakfast', 'Lunch', 'Dinner', 'Snack', 'Post Workout', 'Mid-Morning', 'Midnight']

const STAGE_MESSAGES = [
  { stage: 'Stage 1 of 2', label: 'Identifying food items…', sub: 'Vision analysis in progress' },
  { stage: 'Stage 2 of 2', label: 'Calculating clinical nutrition…', sub: 'Consulting your health profile' },
  { stage: 'Finalising', label: 'Saving your meal log…', sub: 'Almost done' },
]

const MACRO_COLORS: Record<string, string> = {
  Calories: '#e8a23a',
  Protein:  '#35b64b',
  Carbs:    '#3b82f6',
  Fat:      '#ef4444',
  Sodium:   '#8b5cf6',
}

// ─── Props ────────────────────────────────────────────────────────────────

interface AddFoodModalProps {
  isOpen: boolean
  onClose: () => void
  onSuccess: () => void
  isEdit?: boolean
  initialData?: {
    id?: string
    description: string
    proteinGrams: number
    calories: number
    mealType: string
    date: string
  }
  selectedDate: string
}

export function AddFoodModal({ isOpen, onClose, onSuccess, isEdit, initialData, selectedDate }: AddFoodModalProps) {
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  // Notifications & Background tasks context
  const { backgroundScans, startBackgroundScan, desktopEnabled, toggleDesktopNotifications } = useNotifications()
  const [currentTaskId, setCurrentTaskId] = useState<string | null>(null)

  // Tab state
  const [activeTab, setActiveTab] = useState<'manual' | 'ai'>('manual')

  // Manual form state
  const [mealType, setMealType] = useState('')
  const [description, setDescription] = useState('')
  const [proteinGrams, setProteinGrams] = useState('')
  const [calories, setCalories] = useState('')
  const [date, setDate] = useState(selectedDate)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [richPayload, setRichPayload] = useState<any>(null)
  const [jsonPayload, setJsonPayload] = useState('')

  // AI tab state
  const [aiPhase, setAiPhase] = useState<Phase>('input')
  const [stageIndex, setStageIndex] = useState(0)
  const [imageFile, setImageFile] = useState<File | null>(null)
  const [imagePreviewUrl, setImagePreviewUrl] = useState<string | null>(null)
  const [aiDescription, setAiDescription] = useState('')
  const [aiMealType, setAiMealType] = useState('')
  const [aiDate, setAiDate] = useState(selectedDate)
  const [isDragOver, setIsDragOver] = useState(false)
  const [aiError, setAiError] = useState('')
  const [aiErrorCode, setAiErrorCode] = useState<number | null>(null)
  const [aiResult, setAiResult] = useState<MealAnalysisApiResponse | null>(null)

  const stageTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const cameraInputRef = useRef<HTMLInputElement>(null)
  const galleryInputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    if (isOpen && isEdit && initialData) {
      setMealType(initialData.mealType)
      setDescription(initialData.description)
      setProteinGrams(initialData.proteinGrams.toString())
      setCalories(initialData.calories.toString())
      setDate(initialData.date)
      setRichPayload(null)
      setJsonPayload('')
      setActiveTab('manual')
      setCurrentTaskId(null)
    } else if (isOpen && !isEdit) {
      setMealType('')
      setDescription('')
      setProteinGrams('')
      setCalories('')
      setDate(selectedDate)
      setRichPayload(null)
      setJsonPayload('')
      setActiveTab('manual')
      // Reset AI state
      setAiPhase('input')
      setStageIndex(0)
      setImageFile(null)
      if (imagePreviewUrl) URL.revokeObjectURL(imagePreviewUrl)
      setImagePreviewUrl(null)
      setAiDescription('')
      setAiMealType('')
      setAiDate(selectedDate)
      setAiError('')
      setAiErrorCode(null)
      setAiResult(null)
      setCurrentTaskId(null)
    }
    return () => {
      if (stageTimerRef.current) clearTimeout(stageTimerRef.current)
    }
  }, [isOpen, isEdit, initialData, selectedDate])

  const currentTask = currentTaskId ? backgroundScans.find(t => t.id === currentTaskId) : null

  useEffect(() => {
    if (!currentTask) return

    if (currentTask.status === 'success') {
      if (stageTimerRef.current) clearTimeout(stageTimerRef.current)
      setAiResult(currentTask.result)
      setAiPhase('results')
    } else if (currentTask.status === 'failed') {
      if (stageTimerRef.current) clearTimeout(stageTimerRef.current)
      const rawMsg = currentTask.error || 'Analysis failed'
      const codeMatch = rawMsg.match(/(\d{3})/)
      const code = codeMatch ? parseInt(codeMatch[1], 10) : null
      setAiErrorCode(code)
      setAiError(rawMsg)
      setAiPhase('input')
      setCurrentTaskId(null)
    }
  }, [currentTask])

  const isNotificationsEnabled = desktopEnabled && typeof window !== 'undefined' && 'Notification' in window && Notification.permission === 'granted'

  // ── Manual form submit ────────────────────────────────────────────────
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let finalPayload: any = null

    if (jsonPayload.trim()) {
      try {
        const parsed = JSON.parse(jsonPayload)

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const getVal = (keys: string[], fallback: any = null) => {
          for (const k of keys) {
            if (parsed && typeof parsed === 'object' && k in parsed) {
              return parsed[k]
            }
          }
          return fallback
        }

        // Normalize timestamp
        let parsedTimestamp = getVal(['timestamp', 'createdAt'])
        if (parsedTimestamp && typeof parsedTimestamp === 'object' && '$date' in parsedTimestamp) {
          parsedTimestamp = parsedTimestamp['$date']
        }

        const parsedDate = getVal(['date', 'dateString', 'date_string'], date)
        const parsedMealType = getVal(['mealType', 'meal_type', 'meal'], mealType)
        const parsedDescription = getVal(['description', 'mealLabel', 'meal_label'], description)

        const parsedCalories = getVal(['calories', 'calories_kcal', 'totalCalories'])
        const parsedProtein = getVal(['proteinGrams', 'protein_grams', 'protein', 'totalProteinGrams'])

        const numCalories = parsedCalories !== null && parsedCalories !== undefined
          ? Math.round(parseFloat(parsedCalories))
          : (calories ? Math.round(parseFloat(calories)) : null)
        const numProtein = parsedProtein !== null && parsedProtein !== undefined
          ? Math.round(parseFloat(parsedProtein))
          : (proteinGrams ? Math.round(parseFloat(proteinGrams)) : null)

        if (!parsedDescription) {
          throw new Error('Description is required (not found in JSON or inputs)')
        }
        if (numCalories === null || isNaN(numCalories) || numCalories < 0) {
          throw new Error('Calories is required and must be non-negative (not found in JSON or inputs)')
        }
        if (numProtein === null || isNaN(numProtein) || numProtein < 0) {
          throw new Error('Protein is required and must be non-negative (not found in JSON or inputs)')
        }
        if (!parsedMealType) {
          throw new Error('Meal Type is required (not found in JSON or inputs)')
        }
        if (!parsedDate) {
          throw new Error('Date is required (not found in JSON or inputs)')
        }

        finalPayload = {
          description: parsedDescription,
          calories: numCalories,
          proteinGrams: numProtein,
          mealType: parsedMealType,
          date: parsedDate,
          timestamp: parsedTimestamp,
          mealQuality: getVal(['mealQuality', 'meal_quality', 'letterGrade', 'letter_grade']),
          notes: getVal(['notes']),
          recipeCategory: getVal(['recipeCategory', 'recipe_category']),
          serving: getVal(['serving']),
          servingNotes: getVal(['servingNotes', 'serving_notes']),
          sourceNotes: getVal(['sourceNotes', 'source_notes']),
          importKey: getVal(['importKey', 'import_key']),
          analysis_metadata: getVal(['analysisMetadata', 'analysis_metadata']),
          meal_items: getVal(['mealItems', 'meal_items']),
          total_summary: getVal(['totalSummary', 'total_summary']),
          gaps_and_warnings: getVal(['gapsAndWarnings', 'gaps_and_warnings']),
          technical_diagnostic: getVal(['technicalDiagnostic', 'technical_diagnostic']),
          acne_impact_assessment: getVal(['acneImpactAssessment', 'acne_impact_assessment']),
          health_analysis: getVal(['healthAnalysis', 'health_analysis']),
          recomposition_assessment: getVal(['recompositionAssessment', 'recomposition_assessment']),
          satiety_and_energy_profile: getVal(['satietyAndEnergyProfile', 'satiety_and_energy_profile']),
          nutritional_balance_diagnostic: getVal(['nutritionalBalanceDiagnostic', 'nutritional_balance_diagnostic']),
          daily_context: getVal(['dailyContext', 'daily_context'])
        }
      } catch (err: any) {
        setError('JSON Error: ' + err.message)
        return
      }
    } else {
      if (!description || !calories || !proteinGrams || !date || !mealType) {
        setError('Please fill in all fields including Meal Type')
        return
      }
      const numCalories = Math.round(parseFloat(calories))
      const numProtein = Math.round(parseFloat(proteinGrams))
      if (isNaN(numCalories) || numCalories < 0 || isNaN(numProtein) || numProtein < 0) {
        setError('Macros must be 0 or greater')
        return
      }
      finalPayload = {
        description,
        calories: numCalories,
        proteinGrams: numProtein,
        mealType,
        date
      }
      if (richPayload) {
        finalPayload.analysis_metadata = richPayload.analysis_metadata
        finalPayload.meal_items = richPayload.meal_items
        finalPayload.total_summary = richPayload.total_summary
        finalPayload.gaps_and_warnings = richPayload.gaps_and_warnings
        finalPayload.technical_diagnostic = richPayload.technical_diagnostic
        finalPayload.acne_impact_assessment = richPayload.acne_impact_assessment
        finalPayload.health_analysis = richPayload.health_analysis
        finalPayload.recomposition_assessment = richPayload.recomposition_assessment
        finalPayload.satiety_and_energy_profile = richPayload.satiety_and_energy_profile
        finalPayload.nutritional_balance_diagnostic = richPayload.nutritional_balance_diagnostic
        finalPayload.daily_context = richPayload.daily_context
      }
    }

    setLoading(true)
    try {
      if (isEdit && initialData?.id) {
        await updateFoodEntry(finalPayload.date, initialData.id, finalPayload)
        toast.success(`Updated "${finalPayload.description}"`)
      } else {
        await addFoodEntry(finalPayload)
        toast.success(`Logged "${finalPayload.description}"`)
      }
      onSuccess()
      onClose()
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) {
      setError(err.message || 'Failed to save food entry')
    } finally {
      setLoading(false)
    }
  }

  // ── AI image handling ─────────────────────────────────────────────────
  const handleImageDrop = useCallback((file: File) => {
    if (!file.type.startsWith('image/')) {
      toast.error('Please upload an image file (JPG, PNG, WEBP, HEIC)')
      return
    }
    if (file.size > 10 * 1024 * 1024) {
      toast.error('Image must be under 10 MB')
      return
    }
    setImageFile(file)
    setImagePreviewUrl(URL.createObjectURL(file))
  }, [])

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragOver(false)
    const file = e.dataTransfer.files[0]
    if (file) handleImageDrop(file)
  }, [handleImageDrop])

  const removeImage = () => {
    setImageFile(null)
    if (imagePreviewUrl) URL.revokeObjectURL(imagePreviewUrl)
    setImagePreviewUrl(null)
  }

  const aiCanSubmit = (imageFile !== null || aiDescription.trim().length > 0) && aiMealType !== ''

  // ── AI stage cycling ──────────────────────────────────────────────────
  const cycleStages = useCallback(() => {
    let idx = 0
    const tick = () => {
      idx = Math.min(idx + 1, STAGE_MESSAGES.length - 1)
      setStageIndex(idx)
      if (idx < STAGE_MESSAGES.length - 1) {
        stageTimerRef.current = setTimeout(tick, 4500)
      }
    }
    stageTimerRef.current = setTimeout(tick, 4500)
  }, [])

  // ── AI submit ─────────────────────────────────────────────────────────
  const handleAiSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setAiError('')
    setAiErrorCode(null)
    if (!aiCanSubmit) {
      setAiError('Add an image or description, and select a meal type.')
      return
    }

    setAiPhase('processing')
    setStageIndex(0)
    cycleStages()

    try {
      const taskId = await startBackgroundScan(imageFile, aiDescription || null, aiMealType, aiDate)
      setCurrentTaskId(taskId)
    } catch (err: unknown) {
      if (stageTimerRef.current) clearTimeout(stageTimerRef.current)
      const rawMsg = err instanceof Error ? err.message : 'Failed to start background scan'
      setAiError(rawMsg)
      setAiPhase('input')
    }
  }

  const handleAiSave = () => {
    onSuccess()
    onClose()
    toast.success(`Logged: ${aiResult?.description || 'AI meal'}`)
  }

  const handleReanalyze = () => {
    setAiPhase('input')
    setAiResult(null)
    setAiError('')
    setAiErrorCode(null)
  }

  if (!isOpen) return null

  return createPortal(
    <div className="finance-modal-backdrop" role="presentation" onClick={onClose}>
      <div
        className="finance-modal-popover add-tx-modal"
        role="dialog"
        aria-modal="true"
        onClick={(e) => e.stopPropagation()}
        style={{ width: 'min(560px, calc(100vw - 42px))', maxHeight: 'min(90vh, 760px)', display: 'flex', flexDirection: 'column' }}
      >
        <button type="button" className="finance-modal-close" onClick={onClose}>
          <X size={15} />
        </button>

        <div className="af-modal-header">
          <h2>{isEdit ? 'Edit Food Entry' : 'Add Food Entry'}</h2>
          <p>Log your meal and track your progress!</p>
        </div>

        {/* ── Tab switcher (hidden while processing or showing AI results) */}
        {!isEdit && aiPhase === 'input' && (
          <div className="type-toggle" style={{ marginBottom: '24px' }}>
            <div className={`type-toggle-slider ${activeTab === 'ai' ? 'slide-right' : ''}`} />
            <button
              type="button"
              className={activeTab === 'manual' ? 'active' : ''}
              onClick={() => setActiveTab('manual')}
            >
              <ClipboardCheck size={14} />
              Manual Entry
            </button>
            <button
              type="button"
              className={activeTab === 'ai' ? 'active' : ''}
              onClick={() => setActiveTab('ai')}
              id="ai-tab-btn"
            >
              <Scan size={14} />
              AI Scan
            </button>
          </div>
        )}

        {/* ═══════════════ MANUAL TAB ═══════════════ */}
        {activeTab === 'manual' && (
          <form onSubmit={handleSubmit} className="add-tx-form" style={{ flex: 1, overflowY: 'auto', paddingRight: '6px' }}>
            <div className="form-group">
              <label>Food Name</label>
              <input
                type="text"
                placeholder="e.g. Paneer Sandwich, Salad..."
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                autoFocus
              />
            </div>

            <div className="form-row-macros">
              <div className="form-group" style={{ flex: 1 }}>
                <label>Meal Type</label>
                <select value={mealType} onChange={e => setMealType(e.target.value)}>
                  <option value="" disabled>Select…</option>
                  {MEAL_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="form-group">
                <label>Date</label>
                <input type="date" value={date} onChange={(e) => setDate(e.target.value)} />
              </div>
            </div>

            <div className="form-row-macros">
              <div className="form-group">
                <label>Protein (g)</label>
                <input
                  type="number" min="0" step="0.01" placeholder="0.00"
                  value={proteinGrams} onChange={(e) => setProteinGrams(e.target.value)}
                />
              </div>
              <div className="form-group">
                <label>Calories (kcal)</label>
                <input
                  type="number" min="0" placeholder="0"
                  value={calories} onChange={(e) => setCalories(e.target.value)}
                />
              </div>
            </div>

            <div className="form-separator" style={{ margin: '16px 0', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <div style={{ flex: 1, height: '1px', background: 'rgba(20, 24, 22, 0.1)' }} />
              <span style={{ padding: '0 12px', fontSize: '11px', color: 'rgba(16, 19, 18, 0.4)', textTransform: 'uppercase', letterSpacing: '0.05em', fontWeight: 600 }}>OR</span>
              <div style={{ flex: 1, height: '1px', background: 'rgba(20, 24, 22, 0.1)' }} />
            </div>

            <div className="form-group">
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '6px' }}>
                <label style={{ margin: 0 }}>Paste AI JSON Payload</label>
                <span className="import-hint" style={{ fontSize: '10px' }}>Paste raw meal log JSON response generated by AI</span>
              </div>
              <textarea
                className="json-textarea"
                placeholder='{&#10;  "description": "Lemon Rice",&#10;  "calories": 472,&#10;  "proteinGrams": 10,&#10;  "mealItems": [ ... ],&#10;  "totalSummary": { ... },&#10;  "acneImpactAssessment": { ... }&#10;}'
                value={jsonPayload}
                onChange={(e) => setJsonPayload(e.target.value)}
                style={{ height: '120px', minHeight: '120px', resize: 'vertical' }}
              />
            </div>

            {error && <p className="add-tx-error">{error}</p>}

            <div className="af-live-macro-preview">
              <div className="af-macro-preview-item">
                <span className="af-macro-label">Calories</span>
                <span className="af-macro-value">{calories || '0'} <em>kcal</em></span>
              </div>
              <div className="af-macro-preview-item">
                <span className="af-macro-label">Protein</span>
                <span className="af-macro-value">{proteinGrams || '0'} <em>g</em></span>
              </div>
            </div>

            <button type="submit" className="add-tx-submit af-submit-btn" disabled={loading} style={{ width: '100%', marginTop: '16px', height: '48px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              {loading ? <Loader2 className="spinner" size={18} /> : 'Save Food'}
            </button>
          </form>
        )}

        {/* ═══════════════ AI TAB ═══════════════════ */}
        {activeTab === 'ai' && (
          <>
            {/* ── Phase 1: Input ──────────────────────────── */}
            {aiPhase === 'input' && (
              <form onSubmit={handleAiSubmit} className="add-tx-form" style={{ gap: 0, flex: 1, overflowY: 'auto', paddingRight: '6px' }}>
                <p style={{ fontSize: '13px', color: 'rgba(16,19,18,0.5)', margin: '0 0 16px', lineHeight: 1.5 }}>
                  Upload a photo or describe your meal — Gemini identifies every item and calculates full clinical nutrition.
                </p>

                {!isNotificationsEnabled && (
                  <div className="af-compact-alert">
                    <Bell size={16} className="af-compact-alert-icon" />
                    <span className="af-compact-alert-text">
                      Enable push alerts to close this modal while Gemini analyses (takes 1-2 mins).
                    </span>
                    <button type="button" onClick={toggleDesktopNotifications} className="af-compact-alert-btn">
                      Enable
                    </button>
                  </div>
                )}

                {/* Drag-drop zone */}
                {imagePreviewUrl ? (
                  <div className="af-image-preview">
